function toast(x){ return; } // UI alerts/toasts disabled by design
function openModal(content){document.getElementById("modal").innerHTML=`<div class="modalbox">${content}<div style="text-align:right;margin-top:16px"><button class="btn" onclick="closeModal()">Close</button></div></div>`;document.getElementById("modal").classList.add("show")}
function closeModal(){document.getElementById("modal").classList.remove("show")}
function nav(){return state.role==="Trainee"?traineeNav:state.role==="Trainer"?trainerNav:adminNav}
function saveView(){location.hash=state.role?encodeURIComponent(state.role)+"/"+encodeURIComponent(state.page):"landing"}
function go(p){state.page=p;persist();saveView();render();window.scrollTo({top:0,behavior:"smooth"})}
function logout(){state.role=null;state.page="Dashboard";persist();saveView();render();toast("Signed out of the demo session")}
function demoLogin(role){state.role=role;state.page="Dashboard";persist();saveView();render();toast(role+" demo session started")}
function help(){openModal(`<h2>Help & Support</h2><p class="muted">CAPACITY CONNECT demonstration support.</p><div class="notice"><b>Prototype note</b><br>This is a functional front-end demonstration. Flask REST API, MySQL and S3-compatible storage are the proposed production architecture.</div><p>For a production deployment, authentication, RBAC, evidence verification, competency rules and storage would be connected to the backend.</p>`)}
function shell(content){
const unread=state.noticeCount||0;
return `<header class="topbar"><button class="iconbtn mobile-toggle" aria-label="Open navigation" onclick="toggleSide()">☰</button><div class="brand"><div class="mark">CC</div><div><b>CAPACITY CONNECT</b><small>Digital Capacity Building & Learning Management Portal</small></div></div><div class="search"><span>⌕</span><input aria-label="Search" placeholder="Search courses, trainers, skills..." onkeydown="if(event.key==='Enter')toast('Search results prepared for: '+this.value)"></div><div class="top-actions"><button class="iconbtn" aria-label="Notifications" onclick="go('Notifications')">●${unread?`<span class="notif-dot">${unread>9?'9+':unread}</span>`:''}</button><button class="iconbtn" aria-label="Help and support" onclick="help()">?</button><div class="avatar" title="${state.role} profile">${state.role[0]}</div><button class="btn small" onclick="logout()">Logout</button></div></header><div class="layout"><aside class="sidebar"><div class="side-title">${state.role} Workspace</div>${nav().map(x=>`<a class="nav ${state.page===x?'active':''}" href="#" onclick="go('${x}');return false"><span class="nav-icon">${icons[x]||"•"}</span><span>${x}</span></a>`).join("")}</aside><main class="main">${content}<footer style="margin-top:35px;padding:18px 0;border-top:1px solid var(--line);color:var(--muted);font-size:11px;text-align:center">CAPACITY CONNECT · SIH 2026 · Prototype for SIH26075 · Accessibility · Privacy · Terms · Help & Support · Contact</footer></main></div>`
}
function page(title,sub,body,action=""){return body}
function kpi(label,value,trend="",kind=""){return `<div class="card kpi ${kind}"><div class="kpi-icon">${icons[label]||"•"}</div><div class="label">${label}</div><div class="value">${value}</div><div class="trend">${trend}</div></div>`}

