function catalogue(){return page("Course Catalogue","Browse organizational learning programmes.",`<div class="card"><div class="formgrid"><div class="field"><label>Search courses</label><input placeholder="Search by course, subject or skill" oninput="filterCourses(this.value)"></div><div class="field"><label>Level</label><select onchange="filterCourses(document.querySelector('.field input').value,this.value)"><option>All levels</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div></div></div><div id="courseGrid" class="grid cards3 section">${courseCards(courses)}</div>`)}
function courseCards(list){return list.map(c=>`<div class="card"><div class="between"><span class="pill blue">${c.level}</span><span class="muted">${c.duration}</span></div><h3 style="margin-top:10px">${c.title}</h3><p class="muted">${c.desc}</p><p><b>Trainer:</b> ${c.trainer}</p><div>${c.skills.map(s=>`<span class="tag">${s}</span>`).join("")}</div><div class="between" style="margin-top:13px"><small>${c.learners} learners · DEMO</small><button class="btn primary small" onclick="openCourse(${c.id})">View Course</button></div></div>`).join("")}
function filterCourses(q="",level="All levels"){const l=level||"All levels";const a=courses.filter(c=>(c.title+c.desc+c.skills.join(" ")).toLowerCase().includes((q||"").toLowerCase())&&(l==="All levels"||c.level===l));const g=document.getElementById("courseGrid");if(g)g.innerHTML=courseCards(a)}
function openCourse(id){const c=courses.find(x=>x.id===id);openModal(`<div class="between"><div><h2>${c.title}</h2><p class="muted">${c.desc}</p></div><span class="pill blue">${c.level}</span></div><div class="formgrid"><div><b>Learning Objectives</b><p>Apply subject knowledge, interpret operational information and develop role-aligned competency.</p></div><div><b>Competencies</b><p>${c.skills.join(" · ")}</p></div><div><b>Learning Resources</b><p>Recorded lecture · Presentation · Study material · Reference document</p></div><div><b>Assessment</b><p>Subject-wise MCQ assessment after learning.</p></div></div><div class="between" style="margin-top:15px"><span class="pill">DEMO COURSE</span><button class="btn primary" onclick="closeModal();go('My Learning');toast('Course enrolled successfully')">Enroll Now</button></div>`)}
