function assessments(){return page("Assessments","Subject-wise MCQs, deadlines and assessment results.",`<div class="card"><div class="between"><div><span class="pill">READY</span><h2 style="margin-top:9px">Atmospheric Observation Basics</h2><p class="muted">12 questions · 20 minutes · Subject: Meteorological Observation · Deadline: 28 Sep 2026</p></div><button class="btn primary" onclick="startAssessment()">Take Assessment</button></div></div>${state.assessmentDone?`<div class="card section"><h2>Latest Assessment Result</h2><div class="grid cards4">${kpi("Score","3/4","Completed","green")}${kpi("Percentage","75%","Recorded","teal")}${kpi("Correct","3","Subject MCQ","green")}${kpi("Competency Update","+8","Contribution","purple")}</div></div>`:""}<div class="card section"><h2>Assessment Record</h2><div class="tablewrap"><table><thead><tr><th>Assessment</th><th>Subject</th><th>Deadline</th><th>Status</th><th>Result</th></tr></thead><tbody><tr><td>Atmospheric Observation Basics</td><td>Meteorological Observation</td><td>28 Sep 2026</td><td><span class="pill">Ready</span></td><td>—</td></tr><tr><td>Synoptic Analysis Check</td><td>Weather Forecasting</td><td>Completed</td><td><span class="pill">Completed</span></td><td>83%</td></tr></tbody></table></div></div>`)}
function startAssessment(){state.assessment=0;state.answers={};openModal(`<div id="assessmentBox"></div>`);renderAssessment()}
function renderAssessment(){const q=qs[state.assessment];document.getElementById("assessmentBox").innerHTML=`<div class="between"><span class="pill blue">QUESTION ${state.assessment+1} OF ${qs.length}</span><b>20:00</b></div><h2 style="margin-top:18px">${q[0]}</h2>${q[1].map((o,i)=>`<label style="display:block;padding:12px;border:1px solid var(--line);border-radius:7px;margin:8px 0"><input type="radio" name="q" value="${i}" ${state.answers[state.assessment]===i?"checked":""}> ${String.fromCharCode(65+i)}. ${o}</label>`).join("")}<div class="between" style="margin-top:18px"><button class="btn" onclick="if(state.assessment>0){state.answers[state.assessment]=+document.querySelector('input[name=q]:checked')?.value;state.assessment--;renderAssessment()}">Previous</button><button class="btn primary" onclick="state.answers[state.assessment]=+document.querySelector('input[name=q]:checked')?.value;if(state.assessment<qs.length-1){state.assessment++;renderAssessment()}else{state.assessmentDone=true;state.assessmentScore=qs.reduce((n,q,i)=>n+(state.answers[i]===q[2]?1:0),0);persist();notify("Assessment completed; competency progress updated","Trainee");closeModal();go('Assessments');toast("Assessment submitted and result calculated")}">${state.assessment===qs.length-1?"Submit Assessment":"Next"}</button></div>`}
